import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Development environment","description":"","frontmatter":{},"headers":[],"relativePath":"dev/environment.md","filePath":"dev/environment.md"}'),o={name:"dev/environment.md"};function i(l,e,p,c,r,d){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="development-environment" tabindex="-1">Development environment <a class="header-anchor" href="#development-environment" aria-label="Permalink to &quot;Development environment&quot;">​</a></h1><p>How to go from a fresh machine to hacking on the kernel.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A Linux host (Debian/Ubuntu tested; anything with the packages below works). Windows: WSL2 gives you exactly this environment.</li><li><code>gcc</code> (14.x tested), <code>binutils</code> (ld), <code>nasm</code> 2.16+, <code>xorriso</code>, <code>mtools</code>, <code>grub-common</code> + <code>grub-pc-bin</code> + <code>grub-efi-amd64-bin</code>, <code>python3</code> (3.9+), <code>zip</code>.</li><li>For testing: <code>qemu-system-x86</code>, <code>ovmf</code>, <code>seabios</code>, <code>ipxe-qemu</code>.</li><li>For the E2E suites: Python <code>pexpect</code> (regression, mega-app smoke) and <code>paramiko</code> (SSH E2E).</li></ul><p><code>tools/build.sh</code> verifies the build set and prints the exact Debian package for anything missing; <code>./build.sh --install</code> installs them when you are root. The no-root alternative is <code>tools/install-toolchain.sh</code> (unpacks a relocatable tree and exports <code>OC_TOOLS</code> - point the Makefile at it with <code>make OC_TOOLS=&lt;tree&gt;</code>; it probes <code>&lt;tree&gt;/usr/...</code> and <code>&lt;tree&gt;/...</code> layouts).</p><h2 id="getting-the-tree" tabindex="-1">Getting the tree <a class="header-anchor" href="#getting-the-tree" aria-label="Permalink to &quot;Getting the tree&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/cubestudio-dev/OpenCubeOS.git</span></span>
<span class="line"><span>cd OpenCubeOS</span></span></code></pre></div><h2 id="sanity-build" tabindex="-1">Sanity build <a class="header-anchor" href="#sanity-build" aria-label="Permalink to &quot;Sanity build&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make all             # userprogs + kernel + ISO + src zip + OTA pkg</span></span>
<span class="line"><span>make test            # host unit tests</span></span>
<span class="line"><span>make run-bios        # boot it</span></span></code></pre></div><p>If all three pass, your environment is good. The full bar for a change is in <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>.</p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ocos/kernel/      L0 core: boot chain, sched, PMM/VMM/heap, usermode</span></span>
<span class="line"><span>ocos/kernel/arch/x86_64/  the 64-bit arch layer (cross archs in build.mk)</span></span>
<span class="line"><span>ocos/services/    one folder per service facet: block, net, audio,</span></span>
<span class="line"><span>                  fs, selfhost (OTA), power, diag, health, klog,</span></span>
<span class="line"><span>                  watchdog, display, tui, crypto, camera, usb, ...</span></span>
<span class="line"><span>ocos/drivers/     one folder per class: storage, net, audio, bus</span></span>
<span class="line"><span>                  (pci/acpi/i2c), usb, input, display, time, misc</span></span>
<span class="line"><span>ocos/interface/   the ring-3 contract headers: l1_lib.h,</span></span>
<span class="line"><span>                  l1svc_ops.h, i18n.h, wizard_lib.h, fs_lib.h,</span></span>
<span class="line"><span>                  editor_core.h</span></span>
<span class="line"><span>ocos/l1apps/      one command = one app = one folder (284 programs)</span></span>
<span class="line"><span>                  + _i18n/ for the flat legacy test programs</span></span>
<span class="line"><span>ocire/            the independent recovery kernel (second L0)</span></span>
<span class="line"><span>tools/            build + test + docs generators</span></span>
<span class="line"><span>tests/            host-side unit tests (make test)</span></span>
<span class="line"><span>docs/             this documentation tree (en + zh mirror)</span></span>
<span class="line"><span>etc/              the default /etc volume content + l0 i18n</span></span></code></pre></div><h2 id="conventions-that-matter-immediately" tabindex="-1">Conventions that matter immediately <a class="header-anchor" href="#conventions-that-matter-immediately" aria-label="Permalink to &quot;Conventions that matter immediately&quot;">​</a></h2><ul><li><code>-Wall -Wextra -Werror</code> - zero warnings, no exceptions.</li><li>Every file carries the SPDX header.</li><li>Kernel/service-visible strings are ASCII English (they are the script + wizard-anchor contract); human surfaces render through <code>tr_()</code> with en+zh resources.</li><li>The command surface only grows (interface freeze, see CONTRIBUTING).</li></ul><h2 id="qemu-recipes" tabindex="-1">QEMU recipes <a class="header-anchor" href="#qemu-recipes" aria-label="Permalink to &quot;QEMU recipes&quot;">​</a></h2><p>Keep these one-liners around:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># quick BIOS boot, serial on stdio</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1 -serial mon:stdio</span></span>
<span class="line"><span></span></span>
<span class="line"><span># UEFI</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -machine q35 -bios /usr/share/ovmf/OVMF.fd \\</span></span>
<span class="line"><span>    -cdrom build/opencube.iso -display none -serial mon:stdio</span></span>
<span class="line"><span></span></span>
<span class="line"><span># with a scratch disk + TUI visible</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -drive file=scratch.qcow2,if=ide -netdev user,id=n1 \\</span></span>
<span class="line"><span>    -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># boot log to a file</span></span>
<span class="line"><span>... -serial file:boot.log</span></span></code></pre></div><p><code>make run-bios</code>, <code>make run-uefi</code>, <code>make run-bios-gui</code>, <code>make shot-bios</code> wrap the common ones (including the /etc volume setup). A relocated toolchain: <code>make OC_TOOLS=&lt;tree&gt; run-bios</code> (and <code>OVMF_FD=...</code> when the tree layout differs).</p>`,18)])])}const m=s(o,[["render",i]]);export{u as __pageData,m as default};
